// Replays proto/testdata/details_vectors.json (generated by
// proto/go/inject/details_vectors_test.go) against proto/ts/src/inject/details.ts,
// then pins the parser's TS-only leniency directly. A failure in the first half
// means Go added or renamed a details field this side doesn't know.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'

import {
  combineRetention,
  isKnownRetention,
  KNOWN_RETENTION_TIERS,
  parseOperatorDetails,
  TEE_MODE_DSTACK_TDX,
  TEE_MODE_NONE,
  TEE_MODE_NVIDIA_CC_SEV_SNP,
  TEE_MODE_NVIDIA_CC_TDX,
  TEE_MODE_STUB,
} from '../src/inject/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
  fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'details_vectors.json'), 'utf8'),
) as Json

describe('details_vectors.json', () => {
  it('is the schema this test expects', () => {
    expect(v.version).toBe(1)
    expect(v.combine_retention.length).toBeGreaterThan(0)
  })

  it('parses a fully populated Go body back unchanged', () => {
    expect(parseOperatorDetails(v.full)).toStrictEqual(v.full)
  })

  it("reads Go's zero time on a minimal body as absent", () => {
    expect(v.minimal.algo_usd_at).toBe('0001-01-01T00:00:00Z')
    const { algo_usd_at: _, ...want } = v.minimal
    expect(parseOperatorDetails(v.minimal)).toStrictEqual(want)
  })

  it('agrees on the retention tiers, strongest first', () => {
    expect([...KNOWN_RETENTION_TIERS]).toEqual(v.known_retention)
  })

  for (const c of v.combine_retention) {
    it(`combineRetention(${JSON.stringify(c.a)}, ${JSON.stringify(c.b)})`, () => {
      expect(combineRetention(c.a, c.b)).toBe(c.want)
    })
  }

  it('agrees on the TEE modes', () => {
    expect([
      TEE_MODE_NONE,
      TEE_MODE_STUB,
      TEE_MODE_NVIDIA_CC_TDX,
      TEE_MODE_NVIDIA_CC_SEV_SNP,
      TEE_MODE_DSTACK_TDX,
    ]).toEqual(v.tee_modes)
  })
})

// Go rejects a whole body over one wrong-typed field; this parser keeps what it
// can. None of this has a Go twin, so it is pinned here.
describe('parseOperatorDetails leniency (TS only)', () => {
  const model = (extra: Json = {}): Json => ({ id: 'm', input_rate_usd_per_1m: 1, output_rate_usd_per_1m: 2, ...extra })

  it('refuses a body that is not a JSON object', () => {
    for (const body of [null, undefined, 'x', 1, [], [{ models: [] }]]) {
      expect(parseOperatorDetails(body)).toBeNull()
    }
  })

  it('drops a wrong-typed top-level field and keeps the rest', () => {
    const got = parseOperatorDetails({
      operator_id: '7',
      node_id: 2,
      proto_version: 9.1,
      oracle_healthy: 'true',
      models: [model()],
    })
    expect(got).toStrictEqual({ node_id: 2, oracle_healthy: false, models: [model()] })
  })

  it('reads models that is not an array as no models', () => {
    expect(parseOperatorDetails({ models: { id: 'm' } })?.models).toEqual([])
    expect(parseOperatorDetails({})?.models).toEqual([])
  })

  it('skips entries without a string id', () => {
    const got = parseOperatorDetails({ models: [{ id: 3 }, { id: '' }, null, 'm', model()] })
    expect(got?.models.map((m) => m.id)).toEqual(['m'])
  })

  // Dropping only the field would turn garbage into a claim: "text only", "free", "flat".
  it('skips a model whose routing, sizing or pricing field is present but malformed', () => {
    const bad: Json[] = [
      { input_modalities: 'text' },
      { output_modalities: { 0: 'text' } },
      { input_modalities: ['text', { type: 'image' }] },
      { input_modalities: [null] },
      { input_rate_usd_per_1m: '0.4' },
      { output_rate_usd_per_1m: -1 },
      { input_rate_usd_per_1m: Number.NaN },
      { input_rate_usd_per_1m: null },
      { cache_read_rate_usd_per_1m: '0.1' },
      { long_context_threshold_tokens: '128000', long_context_input_rate_usd_per_1m: 0.8 },
      { long_context_output_rate_usd_per_1m: -2 },
      { context_window: 1.5 },
      { max_output_tokens: -1 },
      { serves_image_gen: true, image_rate_micro_usdc: '30000' },
      { image_tool_rate_micro_usdc: 2 ** 53 },
      { image_edit_cap_micro_usdc: {} },
      { tool_call_rates_micro_usdc: { zs_web_search: -1, web_search: 10 } },
      { tool_call_rates_micro_usdc: [10] },
      { vendor_tool_call_cap: '5' },
      { vendor_tool_catchall_micro_usdc: -1 },
      { vendor_tool_tokens_per_call: 0.5 },
      { output_rate_usd_per_1m: null },
    ]
    // Every field the full Go body sets, other than the display-only ones, is
    // read by routing, sizing or pricing: a string in any of them skips the
    // model, and so does a fraction in any that Go sends as an integer. Derived
    // from the fixture so a newly ported priced field is covered without a list.
    const displayOnly = new Set([
      'id',
      'reasoning',
      'tool_use',
      'tags',
      'coordinates',
      'source',
      'canonical_id',
      'retention',
      'serves_image_gen',
      'serves_image_edit',
    ])
    const fullModel = v.full.models[0] as Json
    const priced = Object.keys(fullModel).filter((k) => !displayOnly.has(k) && !k.startsWith('weights_'))
    expect(priced.length).toBeGreaterThan(20)
    for (const k of priced) {
      bad.push({ [k]: '1' })
      if (Number.isInteger(fullModel[k])) bad.push({ [k]: 1.5 })
    }
    const got = parseOperatorDetails({
      models: [...bad.map((extra, i) => model({ id: `bad${i}`, ...extra })), model({ id: 'ok' })],
    })
    expect(got?.models.map((m) => m.id)).toEqual(['ok'])
  })

  // Go decodes null into an omitted field.
  it('reads null on an optional priced field as absent, keeping the model', () => {
    const got = parseOperatorDetails({
      models: [model({ cache_read_rate_usd_per_1m: null, context_window: null, tool_call_rates_micro_usdc: null })],
    })
    expect(got?.models[0]).toStrictEqual(model())
  })

  it('reads an empty modality list or tool-rate map as absent', () => {
    const got = parseOperatorDetails({
      models: [model({ input_modalities: [], output_modalities: [], tool_call_rates_micro_usdc: {} })],
    })
    expect(got?.models[0]).toStrictEqual(model())
  })

  it('reads an absent base rate as 0, as Go decodes it', () => {
    const got = parseOperatorDetails({ models: [{ id: 'm' }] })
    expect(got?.models[0]).toStrictEqual({ id: 'm', input_rate_usd_per_1m: 0, output_rate_usd_per_1m: 0 })
  })

  it('drops top-level integers that are negative, fractional, or past 2^53', () => {
    const got = parseOperatorDetails({
      operator_id: -1,
      node_id: 1.5,
      ephemeral_expiry: 1.5,
      ephemeral_issued_at: -1,
      min_charge_output_tokens: 1.5,
      min_charge_algo_txns: '7',
      min_charge_microusdc: 1.5,
      max_tool_iterations: 2 ** 53,
      tool_headroom_per_iteration: 4000,
      models: [],
    })
    expect(got).toStrictEqual({ models: [], oracle_healthy: false, tool_headroom_per_iteration: 4000 })
  })

  // The tier is node-authored; an unrecognized one would let a node mint its own label.
  it('drops an unrecognized retention tier', () => {
    const got = parseOperatorDetails({ models: [model({ retention: 'retains_nothing_trust_me' })] })
    expect(got?.models[0]?.retention).toBeUndefined()
    expect(isKnownRetention('retains_nothing_trust_me')).toBe(false)
    expect(isKnownRetention(undefined)).toBe(false)
  })

  // A mode is a verifier dispatch key: dropping a newer one would hide that the
  // node claims a TEE at all.
  it('carries an unrecognized TEE mode, and drops a block with no mode or mode none', () => {
    expect(parseOperatorDetails({ tee: { mode: 'sev-snp-v9' } })?.tee).toStrictEqual({ mode: 'sev-snp-v9' })
    expect(parseOperatorDetails({ tee: { mode: '' } })?.tee).toBeUndefined()
    expect(parseOperatorDetails({ tee: { mode: TEE_MODE_NONE, evidence_url: '/x' } })?.tee).toBeUndefined()
    expect(parseOperatorDetails({ tee: { evidence_url: '/x' } })?.tee).toBeUndefined()
    expect(parseOperatorDetails({ tee: 'dstack-tdx' })?.tee).toBeUndefined()
  })

  it("reads Go's zero time and unparseable times as absent", () => {
    const got = parseOperatorDetails({
      algo_usd_at: 'not a date',
      tee: { mode: TEE_MODE_DSTACK_TDX, attested_at: '0001-01-01T00:00:00Z', evidence_url: '/v1/zs/attestation' },
    })
    expect(got?.algo_usd_at).toBeUndefined()
    expect(got?.tee).toStrictEqual({ mode: TEE_MODE_DSTACK_TDX, evidence_url: '/v1/zs/attestation' })
  })

  it('keeps only zs_ built-in tools, narrowed to their type', () => {
    const got = parseOperatorDetails({
      builtin_tools: [{ type: 'zs_web_search', name: 'x' }, { type: 'web_search' }, { type: 1 }, 'zs_web_read'],
    })
    expect(got?.builtin_tools).toStrictEqual([{ type: 'zs_web_search' }])
    expect(parseOperatorDetails({ builtin_tools: { type: 'zs_web_search' } })?.builtin_tools).toBeUndefined()
    expect(parseOperatorDetails({ builtin_tools: [] })?.builtin_tools).toBeUndefined()
    expect(parseOperatorDetails({ builtin_tools: [{ type: 'web_search' }] })?.builtin_tools).toBeUndefined()
  })

  it('drops reasoning without a boolean supported, and filters its efforts', () => {
    const got = parseOperatorDetails({
      models: [
        model({ id: 'a', reasoning: { allowed_efforts: ['low'] } }),
        model({ id: 'b', reasoning: { supported: false, allowed_efforts: ['low', 3], default_effort: '' } }),
      ],
    })
    expect(got?.models[0]?.reasoning).toBeUndefined()
    expect(got?.models[1]?.reasoning).toStrictEqual({ supported: false, allowed_efforts: ['low'] })
  })

  it('drops display-only fields with nothing usable in them, keeping the model', () => {
    const got = parseOperatorDetails({
      models: [
        model({ coordinates: { family: '', parameters: -5 }, tags: [1, 2], tool_use: 'yes', source: 3 }),
        model({ id: 'n', coordinates: { variant: 'instruct' }, tool_call_rates_micro_usdc: { web_search: 0 } }),
      ],
    })
    expect(got?.models[0]).toStrictEqual(model())
    expect(got?.models[1]?.coordinates).toStrictEqual({ variant: 'instruct' })
    // 0 is a real rate (free), not an omitted one.
    expect(got?.models[1]?.tool_call_rates_micro_usdc).toStrictEqual({ web_search: 0 })
  })
})
